// Render custom inline SVG Suit Icons instead of heavy image resources
const SuitIcon: React.FC<{ suit: string; size: number }> = ({ suit, size }) => {
  const color = SUIT_COLOR[suit as keyof typeof SUIT_COLOR] || "#000";
  if (suit === "hearts") {
    return (
      <svg width={size} height={size} viewBox="0 0 24 24" fill={color}>
        <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
      </svg>
    );
  }
  if (suit === "diamonds") {
    return (
      <svg width={size} height={size} viewBox="0 0 24 24" fill={color}>
        <path d="M12 2L2 12l10 10 10-10L12 2z" />
      </svg>
    );
  }
  if (suit === "spades") {
    return (
      <svg width={size} height={size} viewBox="0 0 24 24" fill={color}>
        <path d="M12 2C9 6.5 4 10.5 4 13c0 3.5 3 5 5 5s2.5-1.5 3-2.5c.5 1 1 2.5 3 2.5s5-1.5 5-5c0-2.5-5-6.5-8-11zm0 18v2h-2v-2h2z" />
      </svg>
    );
  }
  // Default: Clubs
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill={color}>
      <path d="M12 2a4 4 0 014 4c0 .88-.29 1.7-.78 2.36A4.5 4.5 0 0119.5 12a4.5 4.5 0 01-4.5 4.5H13v1.5a3 3 0 012.82 2h-7.64A3 3 0 0111 18v-1.5H9a4.5 4.5 0 01-4.5-4.5 4.5 4.5 0 014.28-4.64C8.29 7.7 8 6.88 8 6a4 4 0 014-4z" />
    </svg>
  );
};

